import React from 'react';
import Image from 'next/image';
import logoImg from '@/assets/Job10_1.png';

interface Job10LogoProps {
  className?: string;
  size?: number;
  height?: number;
}

export const Job10Logo: React.FC<Job10LogoProps> = ({ className = '', size, height }) => {
  const h = height || (size ? Math.round(size * 1.1) : 44);
  const w = Math.round(h * (845 / 297));

  return (
    <div className={`job10-logo-group ${className}`}>
      <Image
        src={logoImg}
        alt="Job10 - Get an interview within 10 minutes!"
        width={w}
        height={h}
        className="job10-logo-img"
        priority
      />
    </div>
  );
};
